<table role="presentation" cellspacing="0" cellpadding="0" width="100%" style="background:#faf8f5;font-family:Arial,sans-serif;color:#292625"><tr><td align="center" style="padding:24px 12px"><table role="presentation" cellspacing="0" cellpadding="0" width="600" style="max-width:600px;width:100%;background:#fff;border:1px solid #e9e3dc"><tr><td style="padding:28px 30px;border-bottom:1px solid #e9e3dc;font:22px Georgia,serif">ANNA ACCESORII NUNTĂ</td></tr><tr><td style="padding:30px"><h1 style="font:normal 29px Georgia,serif;margin:0 0 18px">Comanda dumneavoastră a fost înregistrată</h1><p style="line-height:1.6;margin:0 0 20px">Comanda dumneavoastră a fost înregistrată. Vă vom contacta telefonic pentru confirmarea detaliilor înainte de procesare.</p><p style="line-height:1.7;margin:0 0 22px">Comanda: <strong>#<?= $e($order->order_number) ?></strong><br>Data: <?= $e(date('d.m.Y H:i', (int) $order->created_at)) ?><br>Status: <strong>În așteptarea confirmării telefonice</strong></p><table role="presentation" cellspacing="0" cellpadding="0" width="100%" style="border-top:1px solid #e9e3dc"><?php foreach ($order->items as $item): $image = OrderEmail::imageUrl($item->product_image); ?><tr><td width="84" valign="top" style="padding:16px 8px 16px 0;border-bottom:1px solid #eee9e3"><?php if ($image): ?><img src="<?= $e($image) ?>" alt="<?= $e($item->product_title) ?>" width="72" height="82" style="display:block;object-fit:cover;border:0"><?php else: ?><span style="font-size:12px;color:#80766e">Imagine indisponibilă</span><?php endif; ?></td><td valign="top" style="padding:16px 8px;border-bottom:1px solid #eee9e3"><strong><?= $e($item->product_title) ?></strong><br><span style="font-size:13px;color:#80766e"><?= (int) $item->quantity ?> × <?= $e($item->unit_price) ?> MDL</span></td><td align="right" valign="top" style="padding:16px 0;border-bottom:1px solid #eee9e3;white-space:nowrap"><?= $e($item->line_total) ?> MDL</td></tr><?php endforeach; ?></table><p style="text-align:right;line-height:1.7">Subtotal produse: <strong><?= $e($order->subtotal) ?> MDL</strong><br>Total produse: <strong><?= $e($order->total) ?> MDL</strong></p><p style="line-height:1.6">Livrare: <?= $e($method) ?><?php if ($order->delivery_address): ?><br>Adresă: <?= $e($order->delivery_address) ?><?php endif; ?><?php if ($order->additional_information): ?><br>Informații suplimentare: <?= nl2br($e($order->additional_information)) ?><?php endif; ?></p><p style="font-size:13px;color:#6b625c">Costul livrării, dacă se aplică, va fi confirmat separat.</p></td></tr><tr><td style="padding:20px 30px;background:#f6f2ed;color:#6b625c;font-size:13px">Anna Accesorii Nuntă · Vă mulțumim pentru comandă.</td></tr></table></td></tr></table>
